css:
.d-st{box-sizing:border-box;width:300px;max-width:100%;height:150px;overflow-x:hidden;overflow-y:auto;border:1px solid var(--line);border-radius:10px;background:var(--bg)}
.d-st-head{position:sticky;top:0;z-index:1;padding:8px 12px 6px;background:var(--bg);border-bottom:1px solid var(--line)}
.d-st-bar{height:6px;border:1px solid var(--line);border-radius:2px;background:var(--paper)}
.d-st-fill{display:block;height:100%;border-radius:2px;background:var(--ink);transform-origin:0 50%;transform:scaleX(0);animation:d-scroll-timeline-bar-grow steps(6) both;animation-timeline:scroll(nearest)}
.d-st-scale{display:flex;justify-content:space-between;margin-top:4px}
.d-st-tick{display:block;width:1px;height:4px;background:var(--faint)}
.d-st-body{padding:0 12px 16px}
.d-st-h{margin:12px 0 2px;font-family:var(--font-mono);font-size:11px;letter-spacing:.08em;color:var(--muted)}
.d-st-p{margin:0;font-size:11px;line-height:1.6;color:var(--faint)}
.d-st:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
@keyframes d-scroll-timeline-bar-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
